// Lab Check-offs.html — every skill in the ECC Skills Lab Practice & Test-off Manual (Fall 2026), in our own words.
// Each skill: id, group, title, nrs (this course's test-off or lab week, from the syllabus), goal,
// parts [{ h, steps: [text, why, critical?] }], flags (where the checklist differs from the med-surg book or current
// guidance — the checklist still decides the test-off), know (what the evaluator may ask you to state), links.
// "Critical" marks the safety-critical steps (our marking; the manual grades every step). No names or phone numbers.
window.LAB_GROUPS = [['infection', 'Infection control'], ['care', 'Basic care'], ['assess', 'Assessment'], ['meds', 'Medications'], ['iv', 'IV therapy and blood'],
  ['airway', 'Airway and chest tubes'], ['elim', 'Catheters and mobility'], ['ob', 'Mother and newborn'], ['doc', 'Documentation']];

window.LAB_SKILLS = [
  // ===== Infection control =====
  { id: 'hand', group: 'infection', title: 'Hand hygiene', goal: 'Clean hands are the single best way to stop infections spreading — yours and your clients’.',
    parts: [
      { h: 'Soap and water', steps: [
        ['Decide which you need: soap and water when hands are visibly soiled, after caring for a client with C. diff or norovirus, before eating and after the bathroom; an alcohol rub for everything else', 'Alcohol doesn’t cut through dirt and doesn’t kill C. diff spores — friction and running water wash them away.', true],
        ['Push up your sleeves and take off jewelry', 'Rings and watches hide microbes and keep soap off the skin under them.'],
        ['Run the water warm', 'Hot water dries and cracks skin, and cracked skin holds more bacteria.'],
        ['Hands lower than the wrists; wet the hands and wrists under running water', 'Water runs from the cleaner wrists toward the dirtier fingertips and off into the sink.', true],
        ['Apply about 5 mL (1 teaspoon) of liquid or foam soap', 'Enough to cover every surface.'],
        ['Lather with vigorous, circular friction, fingers pointing down', 'Friction lifts microbes off the skin; the soap holds them.'],
        ['Scrub between the fingers, the palms, the backs of the hands, and with the fingers interlaced', 'Thumbs, fingertips and between the fingers are the spots most often missed.'],
        ['Clean under the fingernails', 'Most of the bacteria on hands live under the nails.'],
        ['Scrub at least 20 seconds — 40 to 60 seconds when hands are soiled', 'It is the time that lets friction and soap work.', true],
        ['Rinse well, hands still lower than the elbows', 'Rinsing carries the loosened microbes down and off.'],
        ['Blot dry from the fingertips toward the wrists and forearms, a separate paper towel for each hand', 'Drying goes from clean to less clean; damp hands spread more germs than dry ones.'],
        ['Turn off the faucet with a clean, dry paper towel', 'The handle was touched with dirty hands — don’t pick that up again.', true]] },
      { h: 'Alcohol-based hand rub', steps: [
        ['If your hands are visibly soiled, wash with soap and water instead', 'Alcohol can’t get through dirt or body fluids.', true],
        ['Apply a palmful (about a quarter-sized amount) — enough to wet every surface of the hands and wrists', 'Too little dries before it has worked.'],
        ['Rub it over all surfaces of the hands and fingers with friction', 'The same coverage as a wash: between the fingers, the thumbs, the fingertips.'],
        ['Keep rubbing until your hands are dry (about 20–30 seconds)', 'Alcohol kills as it evaporates; wiping it off early means it didn’t finish.', true]] }],
    know: ['The WHO’s five moments: before touching a client, before a clean or aseptic task, after a body-fluid exposure risk, after touching a client, and after touching the client’s surroundings.', 'Why soap and water for C. diff: alcohol doesn’t kill its spores.'] },

  { id: 'ppe', group: 'infection', title: 'Putting on and taking off PPE', goal: 'PPE puts a barrier between you and the client’s microbes; the order you put it on and take it off keeps the contaminated outside off your skin.',
    parts: [
      { h: 'Putting on: gown → mask or respirator → goggles or face shield → gloves', steps: [
        ['Decide what PPE the client’s precautions and the task call for', 'Contact: gown and gloves. Droplet: a surgical mask. Airborne: a fit-tested N95 and a negative-pressure room.', true],
        ['Hold the gown with the opening toward your back', ''],
        ['Slide your arms into the sleeves one at a time, keeping it above the waist', ''],
        ['Wrap it around to cover the back of your clothes', 'Your uniform must be completely covered.'],
        ['Tie it at the neck and the waist', ''],
        ['Choose a surgical mask or a respirator for the precautions', 'An N95 filters tiny airborne particles; a surgical mask blocks droplets.', true],
        ['Surgical mask: over the nose and mouth, cupped under the chin; press the metal strip to the bridge of your nose', 'Gaps at the nose let droplets around the mask.'],
        ['Tie or loop it at the middle of the head and neck', ''],
        ['Respirator: seal-check it every time you put it on', 'Breathe in sharply — it should pull in; breathe out — no air leaking at the edges.', true],
        ['Goggles or face shield over the eyes without touching the inside; adjust to fit', 'The eyes are a way in for splashes.'],
        ['Gloves: the right size, pulled over the gown’s cuffs', 'No bare skin at the wrist.', true],
        ['Keep your hands away from your face; change gloves when torn or heavily soiled', 'Gloved hands spread germs as well as bare ones do.']] },
      { h: 'Taking off (your checklist’s order: gloves → gown → goggles → mask)', steps: [
        ['Gloves: pinch the outside of one glove at the wrist and peel it off inside out; hold it in the gloved hand', 'Only glove touches glove.', true],
        ['Slide ungloved fingers under the cuff of the other glove and peel it off over the first', 'Clean skin touches only the inside of the glove.', true],
        ['Ball up the gloves and discard them', ''],
        ['Gown: pull it away from your body at the front so the ties break', 'You never reach behind your back with dirty hands.'],
        ['Pull it down over your arms, holding both shoulders in one hand, and roll it inside out into a bundle held away from you', 'The contaminated outside ends up inside the bundle.'],
        ['Discard it in the right container', ''],
        ['Goggles or face shield: lift off from the back by the band without touching the front', 'The front was in the splash zone.', true],
        ['Reusable eyewear into the container for cleaning; disposable into the trash; wash your hands', ''],
        ['Mask or respirator: grasp the bottom ties or elastic, then the top, and lift it off without touching the front', 'The front is the most contaminated part.', true],
        ['Discard it and perform hand hygiene', 'Clean hands after all PPE is off — and any time they get contaminated while removing it.', true]] }],
    flags: ['The CDC’s order for taking PPE off is gloves, goggles or face shield, gown, then mask or respirator — or the gown and gloves together, then the eyewear, then the mask. Your checklist takes the gown off before the goggles. Both keep the dirty outside away from you; for the test-off, follow the checklist.', 'A respirator comes off after you leave the room and close the door (CDC).'] },

  { id: 'sglove', group: 'infection', title: 'Sterile gloves', goal: 'Sterile gloves let you touch sterile equipment and open skin without bringing microbes with you — as long as sterile only ever touches sterile.',
    parts: [
      { h: 'Putting on', steps: [
        ['Perform hand hygiene', '', true],
        ['Set up a work surface at waist level, where you can see it', 'Anything below the waist or out of sight counts as contaminated.', true],
        ['Check the package: sterile, dry, no holes, punctures or water stains, not expired', 'Moisture wicks microbes through the wrapper.', true],
        ['Open the outer wrapper; place the inner package on a clean surface', ''],
        ['Fold back the inner wrapper to show the gloves — cuffs toward you, fingers pointing away, left and right on their sides', ''],
        ['With the thumb and index finger of the other hand, pick up the first glove by the folded cuff edge (its inside) and slip your fingers in; pull it up to the wrist', 'Bare skin may touch only the inside of the cuff.', true],
        ['If fingers land in the wrong places, leave them until both gloves are on; never let the outside touch anything that isn’t sterile', 'Fixing it with the bare hand would contaminate the glove.', true],
        ['Second glove: slide the four gloved fingers under its cuff and pull it on', 'Gloved fingers touch only the outside of the second glove — sterile to sterile.', true],
        ['Adjust both gloves with the other gloved hand until comfortable', ''],
        ['Touch only sterile items; keep your hands above the waist and in front of you', 'Out of sight or below the waist means contaminated.', true]] },
      { h: 'Taking off', steps: [
        ['Grasp one glove near the cuff and pull from the wrist toward the fingertips until it folds over', ''],
        ['Grab the fold and pull it off inside out, away from your body', ''],
        ['Hold the removed glove balled up in the palm of the gloved hand', ''],
        ['Slip two bare fingers inside the cuff of the remaining glove', 'Clean skin touches only the inside.', true],
        ['Peel it down inside out over the first glove so it encloses it', ''],
        ['Don’t touch the outside of either glove; discard them and perform hand hygiene', '']] }] },

  { id: 'sfield', group: 'infection', title: 'Preparing a sterile field', goal: 'A sterile field is a work surface where only sterile items touch — for catheter insertion, dressing changes and trach care.',
    parts: [
      { h: 'Opening the field', steps: [
        ['Perform hand hygiene; put on PPE as needed', '', true],
        ['Identify the client with two identifiers and explain', ''],
        ['Check the kit or tray: dry, unopened, not expired', '', true],
        ['Choose a work area at waist level or higher', '', true],
        ['Open the outer cover, take out the kit and discard the cover', ''],
        ['Place the kit in the center of the surface with its top flap on the far side', 'Opening the far flap first means you never reach over the open field.', true],
        ['Open the far flap away from you, then the sides, then the near flap last (or peel the edges apart)', ''],
        ['Lift a sterile drape by its corners, touching no more than the outer inch; let it fall open away from your body, above the waist and the table', 'The 1-inch border is treated as not sterile.', true],
        ['Lay it flat, moisture-proof (shiny or blue) side down, touching nothing else; any part hanging off the table is contaminated', 'The moisture barrier keeps wetness from wicking germs up from the table.'],
        ['Add items by peeling their wrappers partway and dropping them onto the field from about 6 inches — never onto the border or onto each other', 'Your hands and the outside of the wrapper never cross the field.', true],
        ['Add the other sterile items you need', '']] },
      { h: 'Pouring a sterile solution', steps: [
        ['Check the solution and its expiration date', ''],
        ['Open it and set the cap on the table, edges up (inside facing up)', 'The inside of the cap must stay sterile so you can recap it.', true],
        ['Palm the label and pour from 4–6 inches above the container', 'Palming keeps drips off the label; the height keeps the bottle from touching the field.'],
        ['Pour slowly into the sterile container on the field without splashing', 'A wet spot wicks contamination up through the field.', true],
        ['Touch only the outside of the cap when recapping; label a bottle you’ll reuse with the date and time opened', ''],
        ['Remove PPE and perform hand hygiene', '']] }],
    know: ['Sterile touches only sterile; if in doubt, it is contaminated; never turn your back on a sterile field or reach across it.'] },

  // ===== Basic care =====
  { id: 'bath', group: 'care', title: 'Complete bed bath', goal: 'Cleans the skin, prevents breakdown and infection, helps circulation and comfort — and is a head-to-toe skin check.',
    parts: [{ h: 'Steps', steps: [
      ['Gather washcloths, towels, a basin, soap, lotion, deodorant, waterproof pads and a bath blanket', 'Leaving mid-bath leaves the client uncovered and at risk of falling.'],
      ['Fill the basin two-thirds with water at 110–115 °F (43–46 °C)', 'Warm enough for comfort without burning thin or numb skin — check it.', true],
      ['Close the door or curtain; make the client comfortable', ''],
      ['Offer the bedpan, urinal or bathroom', 'Warm water often brings on the urge to void.'],
      ['Loosen the top covers at the foot; fold and remove the blanket', ''],
      ['Lay the bath blanket over the top sheet; have the client hold it while you slide the top sheet out', 'The client stays covered the whole time.'],
      ['Remove the pillow if tolerated and set it on the chair', ''],
      ['Towel under the head; bath blanket over the chest', ''],
      ['Make a mitt of the washcloth so no ends dangle', 'Loose ends drip and feel cold.'],
      ['Wet and wring the mitt; use soap unless it’s contraindicated', ''],
      ['Eyes first, water only: wipe each eyelid from the inner to the outer corner with a different part of the cloth; pat dry', 'Inner to outer keeps debris away from the tear duct; a fresh part of the cloth keeps one eye from infecting the other.', true],
      ['Wash and dry the face, neck and ears', ''],
      ['One side at a time: shoulder, chest, arm and hand', 'Cleanest areas first.'],
      ['Then the hip, leg and foot', ''],
      ['Towel under each leg while the rest of the body stays covered', 'Privacy and warmth.'],
      ['Wash, rinse and pat dry the feet, especially between the toes', 'Moisture between the toes leads to breakdown and fungal infection.'],
      ['Go to the other side; help the client turn with a lift sheet or other device', 'Safe handling for both of you.', true],
      ['Wash, rinse and pat dry the back', ''],
      ['Change the bath water (and your gloves) before perineal care', 'The perineum comes last, with fresh water, so its bacteria aren’t carried to clean skin.', true],
      ['Perineal care: women front to back; men under the scrotum (and pull back and replace the foreskin if uncircumcised)', 'Front to back keeps stool bacteria away from the urethra; a foreskin left pulled back can swell and trap the penis.', true],
      ['Turn the client to clean between the buttocks', ''],
      ['Apply lotion (gloved)', ''],
      ['Clean gown; an incontinence product if needed', ''],
      ['Put the soiled gown in the linen hamper', ''],
      ['Do the 4 Ps (pain, position, potty, possessions), hand hygiene and document', 'The client is left safe, comfortable and with the call light in reach.', true]] }],
    flags: ['Many hospitals now use prepackaged no-rinse cloths (often chlorhexidine) instead of a basin, because basins can hold bacteria. Your checklist uses a basin — do it that way for the test-off.'] },

  { id: 'bed', group: 'care', title: 'Making an occupied bed', goal: 'Clean, wrinkle-free linen for a client who can’t get up — for hygiene, comfort and dignity, and to prevent pressure injuries.',
    parts: [{ h: 'Steps', steps: [
      ['Raise the bed to working height; lower the side rail on your side only', 'Saves your back; the far rail keeps the client from rolling out.', true],
      ['Remove the blanket, fold it and set it on a clean surface', ''],
      ['Turn the client to the far side, facing the raised rail', ''],
      ['Pillow under the head (or between the client and the rail) as needed', ''],
      ['Roll or fan-fold the soiled linen toward the client’s back and tuck it snugly under them', ''],
      ['Cover any wet spots on the soiled linen with a waterproof pad', 'Keeps the clean linen dry.'],
      ['Remove soiled gloves and perform hand hygiene', 'Clean hands for clean linen.', true],
      ['Place the clean bottom sheet and draw sheet on the near half, center fold at the middle of the bed', ''],
      ['Tuck the edges under the mattress and smooth out every wrinkle', 'Wrinkles press into skin and cause pressure injuries.'],
      ['Warn the client about the bump, then roll them toward you over the linen onto the clean side', ''],
      ['Go to the other side, lower that rail, and pull the soiled linen off without letting it touch your uniform; bag it', 'Keeps microbes off your clothes.', true],
      ['Pull the clean linen through; tuck and smooth it', ''],
      ['Spread the top sheet; slide the bath blanket out from underneath', 'The client is never uncovered.'],
      ['Tuck the top sheet and blanket together at the foot; miter the corners', ''],
      ['Make a small toe pleat in the top sheet and spread', 'Room for the feet prevents heel pressure and foot drop.'],
      ['Change the pillowcase: grasp the middle of the closed end and pull the case over the pillow', 'Keeps the pillow off your uniform.'],
      ['Bed in its lowest position, side rails as ordered, 4 Ps', 'A low bed prevents fall injuries.', true]] }] },

  { id: 'postmortem', group: 'care', title: 'Postmortem care', goal: 'Caring for the body with the same respect as in life, preparing it for the family to see and for transfer to the morgue or funeral home.',
    parts: [{ h: 'Steps', steps: [
      ['Death is confirmed and pronounced — by the provider, or by an RN where state law and agency policy allow; your checklist confirms no vital signs, each checked for a full minute', '', true],
      ['Ask the family whether they want time with the client, or to help wash or comb the hair; respect their cultural and religious customs', 'Many families find this part of saying goodbye.', true],
      ['Ask whether an autopsy will be done; if not, remove or cut tubes and lines per agency policy — leave them in for an autopsy or a medical examiner’s case', 'Tubes can be evidence, or needed by the examiner.', true],
      ['Place the body flat on its back, limbs straight at the sides', 'Rigor mortis will fix the body in whatever position it is left.', true],
      ['Close the eyes (unless custom says a family member does it); if they won’t stay closed, place moist gauze over them', ''],
      ['Bathe the body with the same care as in life', ''],
      ['Clean gown, comb the hair, and cover with fresh linen to the chin, arms at the sides', ''],
      ['A pillow under the head; your checklist also raises the head of the bed 30 degrees (about 20 minutes after death)', 'Keeps blood from pooling in the face (livor mortis), which discolors it.', true],
      ['A rolled washcloth under the chin to hold the jaw closed until rigor mortis sets in', ''],
      ['Dentures: your checklist puts them in a labeled cup in the belongings bag — your med-surg book says to put them back in, which keeps the face’s shape; follow agency policy', ''],
      ['Give belongings and valuables (dentures, keys, wallet) to the family, and document what went to whom', ''],
      ['When the family has finished, open the shroud kit and fill out the identification tags', ''],
      ['Apply the chin strap; tie the feet and arms gently with the kit’s ties', ''],
      ['Tags: one on the big toe, one on the outside of the shroud (at the zipper), one on the belongings', 'Correct identification at the morgue and the funeral home.', true],
      ['Lift onto the gurney supporting the head and limbs; keep the head raised', ''],
      ['Document', '']] }],
    flags: ['Rigor mortis usually begins about 2–4 hours after death and is complete in about 12 hours. Your checklist’s “about 10 minutes … up to 6 hours” is earlier than most references. Livor mortis (spelled “liver mortis” in the checklist) is the purplish pooling of blood in the lowest parts of the body.', 'Your med-surg book (Chapter 8, Box 8.8): lower the bed flat with a pillow under the head, put dentures back in, place pads under the hips, and make sure the death certificate is signed before transfer.'] },

  // ===== Assessment =====
  { id: 'vitals', group: 'assess', title: 'Vital signs', goal: 'Baseline numbers, early warning of disease, and the measure of whether treatment is working.',
    parts: [
      { h: 'Oral temperature (electronic)', steps: [
        ['Wait 15–30 minutes after the client eats, drinks or smokes', 'Hot or cold food and smoking change the mouth’s temperature.'],
        ['Probe cover on; turn it on; tip in the back pocket under the tongue (either side of the frenulum); lips closed', 'That pocket sits over blood vessels close to core temperature.', true],
        ['Remove at the beep; read and document', ''],
        ['Discard the cover; clean the thermometer (soap and water or alcohol), rinse and air-dry', '']] },
      { h: 'Glass thermometer (your checklist)', steps: [
        ['Tip in the back pocket under the tongue', ''],
        ['Leave it in for the time on your checklist: oral 5–8 minutes, rectal 3–5 minutes, axillary 8 minutes', ''],
        ['Read it at eye level', ''],
        ['Shake it down, clean it and store it', '']] },
      { h: 'Temporal artery (infrared)', steps: [
        ['Turn it on; place the probe flat on the center of a clean, dry forehead', ''],
        ['Press and hold the scan button while sliding straight across the forehead toward the temple and hairline', 'The temporal artery runs just under the skin of the forehead.'],
        ['Release at the beep; record', '']] },
      { h: 'Tympanic', steps: [
        ['Turn the head to the side and straighten the ear canal: adults, pinna up and back; children, down and back', 'The canal curves differently in young children.', true],
        ['Turn it on; insert gently until the canal is sealed', 'A loose fit reads the air in the canal, not the eardrum.'],
        ['Press and release the scan button; hold it in place until the beep; record', '']] },
      { h: 'Axillary', steps: [
        ['Dry the axilla', 'Moisture cools the skin and lowers the reading.'],
        ['Tip in the middle of the axilla; lower the arm against the side', ''],
        ['Wait for the beep; document', '']] },
      { h: 'Rectal', steps: [
        ['Explain; position on the side with the hips flexed', ''],
        ['Probe cover on; lubricate', ''],
        ['Insert: adults 1–1.5 inches (2.5–3.8 cm), children ½–1 inch, infants ½ inch (1.25 cm)', 'Deeper risks injuring the rectal wall.', true],
        ['Hold it in place — never leave the client', '', true],
        ['Remove at the beep; read and record', '']] },
      { h: 'Peripheral pulses', steps: [
        ['Find and palpate the pulse with the pads of your fingers, not your thumb', 'Your thumb has its own pulse you could count by mistake.', true],
        ['Count 30 seconds and double it if regular; a full 60 seconds if irregular', 'An irregular rhythm can’t be estimated from part of a minute.', true],
        ['Note the rate, rhythm and strength; compare both sides', ''],
        ['Know the sites: temporal, carotid, brachial, radial, femoral, popliteal, posterior tibial, dorsalis pedis', ''],
        ['Feel the carotids one side at a time', 'Pressing both at once can cut blood flow to the brain and slow the heart.', true]] },
      { h: 'Apical pulse', steps: [
        ['Find the sternal notch, slide down to the angle of Louis (2nd intercostal space), then down to the 5th intercostal space', ''],
        ['Move left to the midclavicular line — the point of maximal impulse (PMI)', ''],
        ['Diaphragm of the stethoscope over the PMI; identify S1 and S2', ''],
        ['Count a full minute; note the rate, rhythm and quality', 'Apical rates are always counted for a full minute (before digoxin, for example).', true]] },
      { h: 'Pulse deficit (two nurses)', steps: [
        ['Get a second nurse: one listens at the apex, the other feels the radial pulse', ''],
        ['One calls “start” and “stop,” so both count the same 60 seconds', 'The two counts have to cover the same beats.', true],
        ['Pulse deficit = apical rate − radial rate', 'Some beats are too weak to reach the wrist — common in atrial fibrillation.']] },
      { h: 'Respirations', steps: [
        ['Note the level of consciousness', ''],
        ['Keep your fingers on the pulse with the client’s arm across the chest, so they don’t know you’re counting breaths', 'People change their breathing when they know it’s being watched.', true],
        ['Count 30 seconds and double it if regular; 60 seconds if irregular', ''],
        ['Note the rate, rhythm, depth, effort and any accessory-muscle use', ''],
        ['Look at the color of the lips, face, hands and feet', 'Cyanosis is a late sign.']] },
      { h: 'Blood pressure — the two-step method', steps: [
        ['Client rested 5 minutes, sitting, feet flat, legs uncrossed, back supported', 'Activity, crossed legs and an unsupported back all raise the reading.', true],
        ['Choose the right cuff size (your checklist: about two-thirds of the upper arm for adults, the whole upper arm for children)', 'Too small reads falsely high; too large reads falsely low.', true],
        ['Bare arm (never over clothing), supported at heart level', 'An arm below heart level reads high.'],
        ['Wrap the cuff snugly, bladder over the brachial artery', ''],
        ['Feel the brachial pulse and inflate until it disappears — your estimated systolic', 'Keeps you from missing an auscultatory gap.', true],
        ['Deflate fully and wait about 2 minutes', 'Lets the trapped blood leave the arm.'],
        ['Stethoscope over the brachial artery; inflate 20–30 mm Hg above the estimate', ''],
        ['Release 2–3 mm Hg per second', 'Faster than that misses the true readings.', true],
        ['First sound = systolic; last sound = diastolic', ''],
        ['To repeat, wait about 2 minutes', '']] },
      { h: 'Oxygen saturation', steps: [
        ['Warm, relaxed hand (below heart level for a finger sensor); remove dark nail polish or an artificial nail', 'Cold, poorly perfused fingers and dark polish give false readings.'],
        ['Sensor on a finger, earlobe or toe', ''],
        ['Leave it on until the reading is steady with a good waveform', ''],
        ['Remove it when done (move it to new sites during continuous monitoring)', '']] },
      { h: 'Pain', steps: [
        ['Onset — and the cause, if known', ''],
        ['Location and spread; duration; pattern over time; what it feels like', ''],
        ['What makes it worse, what relieves it, and other symptoms with it', ''],
        ['Use the right scale: 0–10 numeric for adults who can report; CPOT for critically ill clients who can’t; FLACC for young children and nonverbal clients; Wong-Baker FACES for children', 'When the client can report pain, their report is the most reliable measure.', true]] }],
    flags: ['Glass (mercury) thermometers are rarely used in U.S. facilities now — learn the times for your checklist.', 'The American Heart Association sizes the cuff by the arm’s circumference: a bladder about 80% of the circumference long and 40% wide.', 'For a client with advanced dementia who can’t report pain, the PAINAD scale is often used.'],
    know: ['Adult normal ranges: pulse 60–100, respirations 12–20, BP under 120/80, SpO₂ 95–100% (lower targets for some clients with COPD).'] },

  { id: 'h2t', group: 'assess', title: 'Head-to-toe physical assessment', goal: 'A baseline of the whole person, which confirms or questions the history and becomes your nurse’s note and plan of care.',
    parts: [
      { h: 'Start safely', steps: [
        ['Asepsis and safety; hand hygiene; check the room for isolation precautions', '', true],
        ['Introduce yourself; identify the client with two identifiers; explain', '', true],
        ['Listen well, ask good questions and watch for cues; keep privacy and dignity', ''],
        ['Vital signs including pain', '', true],
        ['ABCCS: airway, breathing, circulation, consciousness, safety — suction and oxygen ready', 'Life threats come before the rest of the exam.', true]] },
      { h: 'General appearance and techniques', steps: [
        ['Affect, behavior and anxiety; hygiene; body position; mobility; speech', ''],
        ['Inspection (overall appearance, color), palpation (light, then deep), percussion, auscultation (lungs, heart, bowel)', 'In the abdomen, listen before you touch.']] },
      { h: 'Head, ears, eyes, nose, neck', steps: [
        ['Head position, skull and scalp, facial features; lips, teeth, gums, mucosa and palate; tongue, uvula, tonsils; palpate the scalp and nose; check symmetry', ''],
        ['Ears: canal and eardrum; whisper test; tuning fork (Weber, Rinne); any drainage', ''],
        ['Eyes: visual acuity (Snellen, with glasses on); pupils in light and dim light (PERRLA); the six cardinal gazes; lids, conjunctiva and sclera', ''],
        ['Nose: septum and inside the nostrils; each nostril open; sense of smell; sinuses', ''],
        ['Neck: trachea midline; range of motion; shoulder shrug against resistance (cranial nerve XI); thyroid; lymph nodes; jugular vein distention', 'A trachea pushed off midline can mean a tension pneumothorax.']] },
      { h: 'Chest, heart, abdomen', steps: [
        ['Lungs front and back for adventitious sounds (crackles, wheezes); chest expansion, work of breathing, accessory muscles', 'Accessory-muscle use can mean acute airway obstruction or a collapsed lung.', true],
        ['Jugular distention more than 3 cm above the sternal angle with the client at 45 degrees may mean heart failure', ''],
        ['Heart: carotid pulses one side at a time; the five auscultation areas; apical pulse; S1 and S2; murmurs', ''],
        ['Abdomen: inspect (distention, symmetry, umbilicus, pulsations, waves), listen in all 4 quadrants, then palpate lightly for pain, tenderness and a full bladder', 'Touching first changes the bowel sounds.', true],
        ['Urine (how often, color, odor) and bowel movements (how often, what kind)', '']] },
      { h: 'Skin, limbs, mobility, neuro', steps: [
        ['Skin: color, temperature, moisture, texture, turgor; lesions, rashes, bruises, pressure areas', ''],
        ['Limbs: pain, deformity, swelling, bruises; compare both sides; radial, dorsalis pedis and posterior tibial pulses; color, warmth, movement and sensation (CWMS); capillary refill', ''],
        ['Strength: hand grips; push and pull with the feet against resistance', ''],
        ['Nails: shape, color, capillary refill', ''],
        ['Mobility: full or partial weight bearing, gait and balance, assistive devices', ''],
        ['Neuro: oriented ×3; cranial nerves I–XII; Romberg; coordination; sensation; reflexes; Glasgow Coma Scale', ''],
        ['Genitalia only as the client and setting call for: inguinal nodes, external genitalia, hernias', ''],
        ['Report and document what you found', '', true]] }],
    flags: ['Your checklist’s eye section also lists eye-pressure tests, the slit lamp and the retinal (fundoscopic) exam. Those are done by a provider or eye specialist — know what they are; a nurse’s eye check is acuity, pupils, eye movements and inspection.'] },

  { id: 'neuro', group: 'assess', title: 'Neurological assessment', goal: 'Finding a change in brain function early — level of consciousness changes first.',
    parts: [
      { h: 'Assess', steps: [
        ['Level of consciousness: alert, lethargic, obtunded or confused, semi-comatose (stuporous), comatose — the evaluator picks one level to assess', 'A change in LOC is the earliest sign of neurologic decline.', true],
        ['Pupils: size, shape, equal, reacting to light, accommodation (PERRLA)', ''],
        ['Eye movements: the six cardinal gazes in a conscious client; the oculocephalic (doll’s eyes) reflex in an unconscious one', ''],
        ['Cranial nerves: pupils and vision, smell and taste, the face (smile, tongue out), neck and shoulder strength', ''],
        ['Motor: posture, coordination, gait; muscles for wasting, tremor or twitching; hand-grip strength', ''],
        ['Sensory: pain (where, what kind, how bad), numbness or tingling, temperature, side-to-side differences', ''],
        ['Reflexes: deep tendon (knee, biceps, triceps, brachioradialis) and superficial (abdominal, cremasteric)', ''],
        ['History: seizures, double vision, pain, weakness, bladder or bowel incontinence, headaches, blackouts, fainting; ask relatives if the client can’t answer', '']] }],
    know: ['The levels of consciousness and how to assess each.', 'Decorticate posturing (arms flexed onto the chest): damage above the brainstem, in the cerebral hemispheres. Decerebrate posturing (arms and legs stiffly extended, wrists turned out): brainstem damage — worse.', 'Early signs of rising intracranial pressure: a change in LOC (first), restlessness, headache, pupil changes, weakness. Late signs: Cushing’s triad — rising systolic BP with a widening pulse pressure, a slow pulse and irregular breathing — plus fixed, dilated pupils, posturing and vomiting.', 'Normal ranges: temperature about 97.8–99.1 °F (36.5–37.3 °C), pulse 60–100, respirations 12–20, BP under 120/80, pulse pressure about 40 (30–50).', 'Glasgow Coma Scale: eyes 1–4, verbal 1–5, motor 1–6; total 3–15; 8 or less means coma — protect the airway.', 'One major cause of altered consciousness or a metabolic cause (low glucose, low sodium, hypoxia, liver or kidney failure, drugs).'] },

  { id: 'cv', group: 'assess', title: 'Cardiovascular assessment', nrs: 'Lab · week 5', goal: 'Heart sounds, pulses and perfusion — and recognizing when vague symptoms like fatigue, indigestion or leg swelling are the heart.',
    parts: [
      { h: 'Set up', steps: [
        ['Hand hygiene; PPE if needed', ''],
        ['AIDET (acknowledge, introduce, duration, explanation, thank you); explain in plain words; get consent', ''],
        ['Head of the bed at 45 degrees; expose the chest as needed', ''],
        ['Chest pain: PQRSTU — what provokes or relieves it, its quality, region and radiation, severity 0–10, timing, and what the client thinks is causing it', 'Chest pain is assessed first and fast.', true],
        ['Look around for equipment (oxygen, nitroglycerin spray, walking aids)', '']] },
      { h: 'Inspect and palpate', steps: [
        ['Hands: color, tar staining, fatty deposits (xanthomas), clubbing; compare temperature; capillary refill', ''],
        ['Radial pulse rate and rhythm; compare both wrists; check for a collapsing pulse; brachial pulse volume and character', ''],
        ['Offer to take the BP in both arms', 'A big difference between arms can mean an arterial problem.'],
        ['Carotid pulse — one side at a time', '', true],
        ['Face: pale conjunctivae, a corneal ring (arcus), fatty eyelid plaques (xanthelasma); mouth: central cyanosis, cracks at the corners, a high-arched palate, dental hygiene', ''],
        ['Chest: scars, deformities, visible pulsations', ''],
        ['Jugular venous pressure with the client positioned correctly; hepatojugular reflux if appropriate', ''],
        ['Palpate the apex beat and its position; feel for a heave and for thrills', '']] },
      { h: 'Listen', steps: [
        ['Aortic (2nd intercostal space, right sternal border), pulmonic (2nd, left), Erb’s point (3rd, left), tricuspid (4th–5th, lower left sternal border), mitral (5th, left midclavicular) — diaphragm while feeling the carotid pulse, then the bell', 'Feeling the carotid tells you which sound is S1.', true],
        ['Carotids while the client holds their breath, for a radiating murmur or a bruit', ''],
        ['Sitting forward: lower left sternal border on expiration (aortic regurgitation)', ''],
        ['On the left side: mitral area on expiration, diaphragm (mitral regurgitation, radiating to the axilla) and bell (mitral stenosis)', ''],
        ['Posterior lung fields', 'Crackles can be fluid from heart failure.']] },
      { h: 'Finish', steps: [
        ['Sacral and ankle edema (pitting)', ''],
        ['Back and legs: scars, vein-harvest sites; cyanosis, breathlessness, pallor', ''],
        ['Tell the client you’re done and thank them; PPE off; hand hygiene', ''],
        ['Summarize what you found and suggest next steps (12-lead ECG, glucose, urine dipstick, peripheral vascular exam)', '']] }] },

  { id: 'glucose', group: 'assess', title: 'Measuring blood glucose', nrs: 'Lab · week 6', goal: 'A fingerstick reading you can act on — the meter is only as accurate as your technique.',
    parts: [{ h: 'Steps', steps: [
      ['Check the meter: battery, and the code matches the code on the test-strip vial', 'A mismatched code gives wrong readings.'],
      ['Check the strips’ expiration date', '', true],
      ['Wash and dry hands well (yours, and the client’s finger: warm water, or alcohol left to dry completely)', 'Sugar on the skin raises the reading; wet alcohol dilutes the drop.', true],
      ['Prepare the lancet device; set the depth for the skin’s thickness', ''],
      ['Take a strip from its foil and put it in the meter', ''],
      ['Clean the fingertip (your checklist: with a dry swab)', ''],
      ['Use the side of the 3rd or 4th finger of the nondominant hand, a different finger each time; avoid the thumb, index and little fingers; never the tip or center of the pad', 'The sides have fewer nerve endings; rotating avoids calluses.', true],
      ['Lancet flat against the side of the finger; press firmly, puncture, remove at once', ''],
      ['Gently massage from the palm toward the fingertip to form a drop — don’t squeeze hard', 'Hard squeezing mixes in tissue fluid and lowers the reading.'],
      ['Touch the drop to the tip of the strip', ''],
      ['Press gauze on the puncture site', ''],
      ['Read the result and act on it by protocol (under 70 mg/dL: treat for hypoglycemia)', '', true],
      ['Discard the lancet in the sharps container and everything else safely; document', '', true]] }],
    links: [['Exam 3 Skills.html#glucose', 'Fingerstick glucose (Exam 3 skills)'], ['Exam 3 Skills.html#hypo', 'Hypoglycemia protocol']] },

  // ===== Medications =====
  { id: 'meds', group: 'meds', title: 'Medication administration: oral, sublingual, liquids, eye and ear', goal: 'The right drug to the right client by the right route — with the same three checks every time.',
    parts: [
      { h: 'The three-step method (every drug, every route)', steps: [
        ['Compare the prescriber’s order with the MAR (or EMR)', 'Catches copying (transcription) errors.', true],
        ['Take the drug from storage and compare its label with the MAR; gather what you need', 'Catches picking errors — look-alike packages.', true],
        ['At the bedside: two identifiers, then compare the label with the MAR again — expiration date, dose, route, time and allergies', 'The last check before the drug reaches the client.', true],
        ['Introduce yourself and explain (AIDET); prepare one client’s medications at a time', 'Mixing clients’ medications causes wrong-patient errors.', true],
        ['Work out any dose with the formula D/H × Q = X (desired ÷ have × quantity)', '']] },
      { h: 'Tablets and capsules', steps: [
        ['Split only scored tablets (use a pill cutter)', 'Unscored and extended-release tablets don’t split evenly or safely.', true],
        ['Pour from a bottle into its cap, then into the cup — never into your hand', ''],
        ['Pour the right number of tablets', ''],
        ['Unit-dose package: open it and put the whole package in the cup', ''],
        ['If the client has trouble swallowing, check whether the drug may be crushed, and mix it with a little soft food', 'Never crush extended-release, enteric-coated or sublingual forms.', true],
        ['Drugs due at the same time go in one cup — except any that need a check first (digoxin: the apical pulse), in their own cup', 'So you can hold that one drug without repouring the rest.', true],
        ['Put the cup in the client’s hand, or tip the pills into the mouth from the cup', ''],
        ['Give water to swallow them; stay until all are taken', 'Never leave medications at the bedside.']] },
      { h: 'Sublingual and buccal', steps: [
        ['Sublingual: under the tongue until it has completely dissolved', 'Absorbed straight into the blood — fast, and it skips the liver.'],
        ['Buccal: between the cheek and the teeth until dissolved', ''],
        ['No swallowing, eating or drinking until it has dissolved', '']] },
      { h: 'Liquids', steps: [
        ['Shake if needed; set the cap upside down on the counter', 'Keeps the inside of the cap clean.'],
        ['Palm the label; pour, twisting the bottle slightly at the end', 'Drips run down the far side, not over the label.'],
        ['If it drips over the lip, wipe the outside of the lip with a clean tissue', ''],
        ['Cup at eye level; read at the bottom of the curve (meniscus)', 'Accurate measuring.', true],
        ['Client in high Fowler’s if possible (raise the head of the bed, or side-lying)', 'Prevents aspiration.', true]] },
      { h: 'Eye drops', steps: [
        ['Fowler’s position, head tilted slightly back', ''],
        ['Clean the lid edges from the inner to the outer corner if needed', ''],
        ['Rest the dropper hand on the forehead; pull the lower lid down with the other hand to expose the pocket (conjunctival sac)', 'A steadied hand moves with the head instead of poking the eye.'],
        ['Hold the dropper ½–¾ inch (13–19 mm) above the eye; never let it touch the eye', 'Touching contaminates the bottle and can scratch the cornea.', true],
        ['Client looks up; drop the ordered number into the pocket, not onto the cornea', 'Drops on the cornea sting and trigger blinking.', true],
        ['Client closes the eyes gently', 'Squeezing pushes the drug back out.'],
        ['When the drug has effects on the whole body, press gently on the inner corner (by the tear duct) for 1–2 minutes', 'Keeps the drug from draining into the nose and being absorbed (eye beta-blockers, for example).']] },
      { h: 'Eye ointment', steps: [
        ['Pull the lower lid down; client looks up', ''],
        ['Squeeze a thin ribbon (about 1 inch, 2–2.5 cm) into the pocket; twist your wrist to break it off', ''],
        ['Client closes the eyes 2–3 minutes; warn that vision will blur for a short time', '']] },
      { h: 'Ear drops', steps: [
        ['Drops at room temperature', 'Cold drops in the ear cause dizziness and nausea.', true],
        ['Client on the side, affected ear up', ''],
        ['Check the eardrum for a perforation — don’t give ear drops if it is perforated', 'Drugs could reach the middle ear and damage hearing.', true],
        ['Clean the outer ear with a cotton-tipped applicator if needed — never into the canal', ''],
        ['Fill the dropper with the right amount', ''],
        ['Straighten the canal: adults, pinna up and back; children under 3, down and back', 'The canal’s shape changes with age.', true],
        ['Hold the dropper about ½ inch (1 cm) above the canal; don’t let it touch the ear or your hands', ''],
        ['Squeeze in the ordered number of drops; let gravity carry them down; gently massage the tragus unless it hurts', ''],
        ['Ear up (side-lying) for 2–3 minutes — your checklist also says stay on the side 5–10 minutes', 'Gives the drug time to reach the eardrum.'],
        ['Cotton loosely at the canal opening for 15 minutes if ordered', '']] }],
    flags: ['Your checklist says the drops flow into the “middle ear.” They flow down the ear canal to the eardrum; with an intact eardrum, nothing reaches the middle ear.'],
    links: [['Dosage Calculations.html#t-pitfalls', 'D/H × V practice (Dosage calculations)']] },

  { id: 'inj', group: 'meds', title: 'Injections: intradermal, intramuscular and Z-track', goal: 'The right drug into the right tissue layer, at the right site, with no injury.',
    parts: [
      { h: 'Before any injection', steps: [
        ['Choose the syringe and needle for the volume, the drug and the client’s muscle mass', '', true],
        ['Check the label and expiration date against the MAR when you take it out, before you draw it up', '', true],
        ['Find the site by its landmarks — and know why that site', '', true],
        ['Subcutaneous sites: abdomen, upper and lower back, upper thighs, backs of the upper arms', '']] },
      { h: 'Intradermal (tuberculin skin test)', steps: [
        ['Used for the tuberculin skin test (TST, PPD)', ''],
        ['27-gauge, ⅜–⅝ inch needle on a 1 mL (tuberculin) syringe', ''],
        ['Clean the vial top with alcohol; your checklist injects 0.1 mL of air into the vial, then you draw the 0.1 mL dose', ''],
        ['Site: the inner forearm, about 4 fingerbreadths below the bend of the elbow', ''],
        ['Clean the site with alcohol and let it dry', ''],
        ['Stretch the skin taut; insert bevel up at 5–15 degrees', 'Bevel up, almost flat, keeps the drug just under the top layer of skin.', true],
        ['Inject slowly until a pale bump (wheal) forms; don’t massage', 'The wheal shows it is intradermal; massage spreads it.', true],
        ['Document the site, lot number, manufacturer and expiration date', ''],
        ['Read it in 48–72 hours: measure the induration — the firm raised area, not the redness — in millimeters', '', true]] },
      { h: 'Intramuscular', steps: [
        ['Check the medication; choose the syringe and needle; draw air equal to the dose into the syringe for the vial', ''],
        ['Identify the client with two identifiers; explain', '', true],
        ['Sites: deltoid, ventrogluteal, dorsogluteal, vastus lateralis, rectus femoris', ''],
        ['Deltoid: 2–3 fingerbreadths below the acromion, in the triangle formed between your index finger and thumb', 'Lower risks the radial nerve; small volumes only.', true],
        ['Vastus lateralis (the site for infants and young children): the middle third of the outer thigh, between the greater trochanter and the knee', 'A large muscle away from major nerves and vessels.'],
        ['Ventrogluteal: heel of the hand on the greater trochanter, index finger toward the anterior superior iliac spine, middle finger back along the iliac crest — inject in the V', 'Deep muscle with no large nerves or vessels — the preferred adult site.', true],
        ['Dorsogluteal: the upper outer quadrant, above a line from the posterior superior iliac spine to the greater trochanter', 'Lateral to the sciatic nerve.'],
        ['Clean the site with alcohol and let it dry', ''],
        ['Hold the syringe like a dart, skin taut, and insert at 90 degrees in one quick motion', 'A quick insertion hurts less.', true],
        ['Your checklist: no blood on aspiration → inject slowly (about 5–10 seconds per mL); blood → withdraw, discard and prepare a new dose', ''],
        ['Withdraw at the same angle; light pressure with gauze; bandage as needed', ''],
        ['Your checklist: no more than 1 mL in one site', ''],
        ['Activate the needle’s safety device and discard in the sharps container — never recap', 'Most needlestick injuries happen during recapping.', true],
        ['Watch for a reaction; reassess; document', '']] },
      { h: 'Z-track', steps: [
        ['Choose the needle length and gauge for the client’s fat and the drug', ''],
        ['Draw up the exact dose', ''],
        ['Pull the skin 1–1.5 inches to one side with the nondominant hand and hold it there', 'Displaced skin seals the needle track when it slides back.', true],
        ['Insert at 90 degrees, still holding the skin; inject slowly', ''],
        ['Withdraw straight out at the same angle, then let go of the skin', 'The skin slides over the track so the drug can’t leak back — iron and other irritating drugs stain and burn.', true],
        ['Pressure and a bandage — don’t massage', 'Massage pushes the drug back up the track.'],
        ['Sharps container; hand hygiene; document', '']] }],
    flags: ['Avoid the dorsogluteal site where you can: it sits near the sciatic nerve, and current guidance prefers the ventrogluteal for adults.', 'Aspirating before an IM injection is no longer recommended for vaccines (CDC), and many references drop it at the recommended sites. Your checklist still includes it — do it for the test-off.', 'Volume per site: about 1 mL in the deltoid; up to about 3 mL in the ventrogluteal or vastus lateralis in adults. Your checklist says 1 mL.', 'Your checklist mentions massaging an IM site — for most drugs apply gentle pressure instead.'],
    know: ['Tuberculin results by risk (CDC): positive at 5 mm or more for people with HIV, recent close contacts and the immunosuppressed; 10 mm or more for health care workers, recent arrivals from high-TB countries and others at higher risk; 15 mm or more for people with no risk factors. Your checklist lists 5 and 10.', 'False positives: a past BCG vaccine. False negatives: a weak immune system.'],
    links: [['Dosage Calculations.html#t-parenteral', 'Syringes, needles and injection math (Dosage calculations)']] },

  { id: 'insulin', group: 'meds', title: 'Insulin: one insulin and mixing two', nrs: 'Lab · week 6', goal: 'The exact number of units of the right insulin — a high-alert drug where small errors matter.',
    parts: [
      { h: 'One insulin in a syringe', steps: [
        ['Hand hygiene; select the right insulin (type and strength) against the MAR', '', true],
        ['Use an insulin syringe, for insulin only', 'Insulin syringes are marked in units; others are marked in mL.', true],
        ['Cloudy insulin (NPH): roll the vial between your palms to mix and warm it (vials in use are kept at room temperature)', 'Rolling mixes the suspension without bubbles; shaking makes foam and wrong doses.'],
        ['Open the syringe package onto a clean surface; wipe the rubber top with alcohol and let it dry', ''],
        ['Inject air equal to the dose into the vial, needle at 90 degrees through the stopper', 'Keeps a vacuum from building in the vial.'],
        ['With the syringe still in the vial, turn it upside down, hold it at eye level and draw slightly more than the dose; push out bubbles and the extra to the exact dose', '', true],
        ['Keep the needle and plunger sterile', ''],
        ['Choose the site — rotate within one area such as the abdomen; position and relax the client', 'Rotating prevents fatty lumps that slow absorption.'],
        ['Pinch up less than an inch of skin; insert at 45 or 90 degrees; inject slowly', ''],
        ['Don’t aspirate and don’t massage', 'Aspiration isn’t needed in fatty tissue; massage speeds absorption unpredictably.', true],
        ['Leave the needle in about 5 seconds, then withdraw; light pressure with gauze', 'Lets the whole dose stay in.'],
        ['Snap the needle guard into its locked position once the dose is given (use it unlocked only to carry the needle)', '', true]] },
      { h: 'Two insulins in one syringe — clear before cloudy', steps: [
        ['Add the doses: NPH (cloudy) + NovoLog, Humalog or regular (clear) = the total', '', true],
        ['Draw air equal to the NPH dose and inject it into the NPH vial; remove the needle without drawing any insulin', ''],
        ['Draw air equal to the clear dose and inject it into the clear vial', ''],
        ['With the syringe still in the clear vial, turn it upside down and draw the clear dose', 'Clear goes first: a drop of NPH in the clear vial would make that fast insulin partly slow.', true],
        ['Insert into the NPH vial without pushing the plunger and draw the NPH dose up to the total', 'Pushing the plunger would put clear insulin into the NPH vial.', true],
        ['Check that the syringe holds exactly the total; have a second nurse check per policy', '', true]] }],
    flags: ['Glargine, detemir and degludec are never mixed with any other insulin.'],
    links: [['Exam 3 Skills.html#insulin', 'Drawing up and mixing insulin (Exam 3 skills)'], ['Exam 3 Skills.html#pen', 'Insulin pen injection']] },

  { id: 'gtube', group: 'meds', title: 'Medications through a G-tube', nrs: 'Test-off · week 8', goal: 'Getting each medication into the stomach without clogging the tube, mixing drugs or causing aspiration.',
    parts: [
      { h: 'Before you give anything', steps: [
        ['Explain the procedure; stop the feeding pump', ''],
        ['Fowler’s position (head of the bed at least 30–45 degrees)', 'Prevents aspiration.', true],
        ['Your checklist: listen over the upper abdomen while injecting 10–30 mL of air, and listen for bowel sounds; check for distention, constipation, diarrhea or dehydration', ''],
        ['Aspirate the residual; measure it and look at it', ''],
        ['Return the residual unless you’re testing pH; for a pH test keep 5–10 mL, wet the strip and compare (gastric: 1–4 on your checklist)', 'Returned residual keeps the client from losing acid and electrolytes.'],
        ['Watch for nausea and vomiting; check the stoma for infection or leakage', ''],
        ['Head of the bed at 30–45 degrees', '', true]] },
      { h: 'Preparing and giving', steps: [
        ['Check the MAR against the order with the six rights, using the three-step method', '', true],
        ['Look on the MAR for acid reducers (PPIs, H2 blockers)', 'They raise stomach pH, which changes the pH check.'],
        ['Check that each drug may be crushed and given by tube. Do NOT crush sublingual, extended- or sustained-release, long-acting or enteric-coated forms; use liquids when you can', 'Crushing them ruins the release design — the whole dose at once, or a drug destroyed by stomach acid.', true],
        ['Pour from a multi-dose container without touching the drug; pour the right dose', ''],
        ['Split only scored tablets (pill cutter)', ''],
        ['Crush each tablet separately to a fine powder and mix each with water (your checklist: 30 mL)', 'Drugs mixed together can clog the tube and interact.', true],
        ['Several drugs: keep each one separate (digoxin, for example)', ''],
        ['Head of the bed at least 30 degrees unless that is contraindicated', '', true],
        ['Liquids: shake as needed, palm the label, wipe a dripping lip, measure at eye level', ''],
        ['Flush with 30 mL of warm water before and after the medications, and 15–30 mL between drugs', 'Keeps the tube open and the drugs apart.', true],
        ['Hold the feeding 30 minutes after the medications (longer for some drugs, such as phenytoin — ask the pharmacist)', 'Formula binds some drugs.'],
        ['Keep the client in Fowler’s position 30–60 minutes afterward', '', true],
        ['Document each drug, dose, date, time, route and site, the water given (it counts as intake), and sign', '']] }],
    flags: ['The air “whoosh” test is not a reliable placement check — your med-surg book, the nutrition society (ASPEN) and the Exam 3 skills page use the length mark at the exit site, the pH of the aspirate, and an x-ray for a new tube. Do the checklist’s step for the test-off, but know the evidence.', 'A gastric aspirate of pH 5 or below supports placement in the stomach; it can read higher in clients taking acid reducers.'],
    links: [['Exam 3 Skills.html#feed', 'Tube feeding and medications through a tube (Exam 3 skills)']] },

  // ===== IV therapy and blood =====
  { id: 'ivprime', group: 'iv', title: 'IV drip calculation and priming the tubing', nrs: 'Lab · week 1', goal: 'The right fluid at the right rate through tubing with no air in it.',
    parts: [{ h: 'Steps', steps: [
      ['Review the order for the solution and the rate', '', true],
      ['Decide whether it will run by gravity or on a pump or controller', ''],
      ['Gravity: find the drop factor — it’s on the tubing box', '', true],
      ['Work out the hourly volume and the drops per minute: (total mL ÷ total minutes) × drop factor', '', true],
      ['Explain to the client', ''],
      ['Assess the IV site; note the type of line', ''],
      ['Check that the solution, tubing and pump are sterile, intact and working', 'A cloudy bag or a damaged package means infection risk.', true],
      ['Open the primary tubing; slide the roller clamp 1–2 inches below the drip chamber and close it', 'A closed clamp stops fluid from rushing through before you’re ready.'],
      ['Uncover the bag’s port and the tubing spike, keeping both sterile', '', true],
      ['Spike the bag', ''],
      ['Squeeze the drip chamber to fill it halfway; open the clamp and prime the tubing', 'Half full lets you count drops and keeps air from entering the line.', true],
      ['Clear all the air bubbles; recap the end of the tubing', 'Air in the line can cause an air embolism.', true],
      ['Open the clamp and set the flow rate', ''],
      ['Scrub the hub on the client’s catheter and flush to check that it’s open', '', true],
      ['Connect the tubing to the catheter hub; check the site for swelling', ''],
      ['Reassess HR, RR, BP and signs of infection', ''],
      ['Be ready to explain hypotonic, isotonic and hypertonic solutions', '']] }],
    know: ['Isotonic (0.9% sodium chloride, lactated Ringer’s): stays in the blood vessels — expands volume. Hypotonic (0.45% sodium chloride): moves into the cells — rehydrates them. Hypertonic (3% sodium chloride; D5NS, D5½NS and D5LR in the bag): pulls water out of the cells into the vessels.'],
    links: [['Dosage Calculations.html#t-iv', 'IV rate calculations (Dosage calculations)']] },

  { id: 'ivrate', group: 'iv', title: 'Setting the IV flow rate', nrs: 'Lab · week 1', goal: 'A gravity infusion that runs at the ordered rate — counted, not guessed.',
    parts: [{ h: 'Steps', steps: [
      ['Review the order for the solution and the rate', '', true],
      ['Hand hygiene; identify the client with two identifiers; explain', '', true],
      ['Be ready to explain hypotonic, isotonic and hypertonic solutions', ''],
      ['Gravity or pump?', ''],
      ['Assess the IV site; note the type of line', ''],
      ['Find the drop factor on the tubing box', ''],
      ['Work out the drops per minute: (total mL ÷ total minutes) × drop factor', '', true],
      ['Check the solution and tubing are sterile and intact; spike the bag', ''],
      ['Open the tubing; fill the drip chamber halfway; prime the tubing and clear the air', ''],
      ['Count the drops for a full minute against the second hand while adjusting the roller clamp', 'A full minute is accurate; counting part of a minute multiplies any error.', true],
      ['Mark a strip of tape on the bag with the hourly levels (a time tape)', 'Anyone can see at a glance whether it’s on time.'],
      ['Scrub the hub and flush to check patency; connect the tubing; check the site for swelling', ''],
      ['Reassess HR, RR, BP and signs of infection; listen to the lungs', 'Crackles can mean the fluid is overloading the client.', true]] }],
    links: [['Dosage Calculations.html#t-iv', 'Drops per minute and time tapes (Dosage calculations)']] },

  { id: 'ivpush', group: 'iv', title: 'Giving an IV medication through a saline lock (IV push)', nrs: 'Test-off · week 2', goal: 'An IV drug given at a safe speed into a line you know is open, with the line flushed at the same speed afterward.',
    parts: [{ h: 'Steps', steps: [
      ['Review the order in the EMR and MAR: the drug, dose and instructions', '', true],
      ['Calculate the dose and prepare the medication', '', true],
      ['Identify the client with two identifiers and compare the MAR with the wristband', '', true],
      ['Check the allergy band; ask about allergies and what the reaction was', '', true],
      ['Ask the client to tell you about any pain, swelling or burning at the IV site', 'Early signs of infiltration or phlebitis.'],
      ['Hand hygiene; clean gloves', ''],
      ['Scrub the access port with alcohol for 15 seconds and let it dry', 'Friction and drying time are what kill the germs on the hub.', true],
      ['Push the air out of a prefilled saline syringe; open the extension clamp; flush with 3–5 mL to check that the line is open', 'Resistance, pain or swelling means don’t give the drug.', true],
      ['Attach the medication syringe (needleless)', ''],
      ['Push at the ordered rate, timed with a second hand (or the push-pause method)', 'Too fast causes speed shock.', true],
      ['Attach the saline syringe and flush 3–5 mL at the same rate as the drug', 'The drug still in the line is part of the dose — flush it at the drug’s rate.', true],
      ['Example: morphine 1 mg in 1 mL over 1 minute — push the first 1 mL of the flush over 1 minute, the rest slowly', ''],
      ['Example: furosemide 40 mg in 4 mL over 2 minutes — push the first 1 mL of the flush over 30 seconds, the rest slowly', ''],
      ['Syringes and any filter needles into the sharps container; document per agency policy', '']] }],
    flags: ['Your checklist is titled “Adding medication to IV fluids and piggyback,” but its steps cover an IV push through a saline lock. Ask your instructor whether the test-off also includes hanging a piggyback.'],
    know: ['Why review creatinine and other labs first: many IV drugs are cleared by the kidneys.', 'Before giving, check when the last dose was given; start with the lowest dose and titrate up.'],
    links: [['Dosage Calculations.html#t-parenteral', 'IV push timing and “or fraction thereof” (Dosage calculations)']] },

  { id: 'blood', group: 'iv', title: 'Blood transfusion', nrs: 'Test-off · week 3', goal: 'The right blood to the right client — verified twice by two people — and a reaction caught in its first minutes.',
    parts: [{ h: 'Steps', steps: [
      ['Verify the order: the indication, the rate and any premedication', '', true],
      ['Verify that informed consent is signed', '', true],
      ['Check what the client knows; reinforce what to report (chills, itching, back pain, trouble breathing)', ''],
      ['Give any pretransfusion medications as ordered', ''],
      ['Pick up the blood from the blood bank per agency policy', ''],
      ['Wear gloves to handle the blood product', ''],
      ['With another qualified staff member, recheck the order, consent, labs and the donor blood type', '', true],
      ['Ask the client to state their full name and date of birth; compare with the blood bank form', '', true],
      ['Compare the name and hospital ID number on the wristband with the form', '', true],
      ['Compare the name and ID number on the blood bank form attached to the bag', '', true],
      ['Compare the unit number on the form with the number on the bag', '', true],
      ['Compare the blood type on the form with the blood type on the bag', '', true],
      ['Any mismatch: call the blood bank at once and do not give it', '', true],
      ['All match: both staff sign the form on the bag; record the date and time it was started', ''],
      ['Keep the form attached to the bag; label the blood tubing with the date and time', ''],
      ['Close all the clamps on the Y-tubing', ''],
      ['Spike the normal saline with one of the Y’s spikes and open that clamp only; keep the blood spike capped', 'Normal saline only: dextrose makes red cells clump and burst, and the calcium in lactated Ringer’s starts clotting.', true],
      ['Squeeze the drip chamber to fill it halfway (covering the filter) and prime the set with saline', ''],
      ['Take and record vital signs before starting', 'A baseline makes a reaction recognizable.', true],
      ['Set the drip rate as ordered', ''],
      ['Stay with the client at the start (your checklist: the first 5 minutes), then take vital signs', 'The worst reactions start early.', true],
      ['Vital signs at 15 minutes, 30 minutes, then hourly until it’s done', ''],
      ['When the unit is in: close the clamp nearest the blood, open the saline clamp to flush the set; discard the bag and set per policy', ''],
      ['A second unit may hang on the same set if facility policy allows', '']] }],
    flags: ['Your Exam 2 notes (Chapter 34): stay with the client for the first 15 minutes at a slow rate — that is when most severe reactions show — with vital signs before, at 15 minutes and after; use an 18–20 gauge line and finish within 4 hours. Your checklist says the first 5 minutes; follow it for the test-off and know 15 minutes for exams.'],
    links: [['Exam 2 Map.html#34-white-cell-cancers-and-clotting-failures', 'Transfusion nursing (Exam 2 map, Chapter 34)']] },

  { id: 'reaction', group: 'iv', title: 'Blood transfusion reaction', nrs: 'Test-off · week 3', goal: 'Stopping a reaction before more incompatible blood goes in — and keeping the evidence for the blood bank.',
    parts: [{ h: 'Steps', steps: [
      ['Stop the transfusion at the first sign of a reaction', 'How bad it gets depends on how much blood went in.', true],
      ['Take vital signs; listen to the heart and lungs', '', true],
      ['Notify the provider once the blood is stopped and the client assessed', '', true],
      ['Don’t flush the blood tubing with saline', 'That would push the rest of the blood in the line into the client.', true],
      ['Disconnect the blood set from the IV catheter', '', true],
      ['Keep the IV open: hang new normal saline with new tubing', 'IV access for drugs and fluids.', true],
      ['Put the bag and set, with the blood bank form attached, in a biohazard bag and send them to the blood bank at once', 'The blood bank tests them to find the cause.', true],
      ['Draw blood from the arm opposite the transfusion', 'Blood from the transfusion arm would be mixed with donor blood.', true],
      ['Collect a urine specimen per agency policy', 'Hemoglobin in the urine shows red cells were destroyed.'],
      ['Give medications as prescribed', ''],
      ['Keep checking vital signs often; document', '']] }],
    know: ['Signs of a reaction: fever, chills, itching, hives, flushing, back or chest pain, shortness of breath, wheezing, low blood pressure, a fast pulse, dark urine.', 'Drugs often ordered: an antihistamine, an antipyretic, epinephrine for anaphylaxis, a steroid, IV fluids.'],
    links: [['Exam 2 Map.html#34-white-cell-cancers-and-clotting-failures', 'Transfusion reactions (Exam 2 map, Chapter 34)']] },

  // ===== Airway and chest tubes =====
  { id: 'trach', group: 'airway', title: 'Tracheostomy suctioning and trach care', nrs: 'Test-off · week 4', goal: 'Clearing secretions the client can’t cough out, and keeping the trach and stoma clean and secure.',
    parts: [
      { h: 'Suctioning', steps: [
        ['Assess the need: noisy or wet breathing, visible mucus, gasping or fast breathing, falling SpO₂, a mucus plug in the tube', 'Suction only when needed — each pass irritates the airway and takes oxygen.', true],
        ['Gather and set up the equipment; explain to the client', ''],
        ['Semi-Fowler’s position', ''],
        ['Sterile gloves (the sterile hand touches only the catheter)', '', true],
        ['Measure the insertion depth (your checklist: the corner of the mouth to the earlobe, or the center of the mouth to the angle of the jaw)', ''],
        ['Attach the tubing to the suction machine; set it to 80–120 mm Hg; test it', 'Too much pressure injures the airway lining.', true],
        ['Hold the catheter at the suction depth and turn the machine on', ''],
        ['Pour sterile saline into its container', 'For rinsing the catheter — not for pouring into the airway.'],
        ['Hold the catheter by the end that connects to the suction; keep the end that goes into the trach untouched', '', true],
        ['Before suctioning and between passes: 2–3 breaths with a manual resuscitation bag on 100% oxygen as the client breathes in', 'Suctioning removes oxygen along with secretions.', true],
        ['Hold the catheter between the thumb and forefinger and insert it gently, without suction, about 6 inches or until the client coughs; stop at the measured depth', 'Suction while inserting damages the lining and steals oxygen.', true],
        ['Apply suction while withdrawing — 15 seconds at most — and wait at least 30 seconds between passes', 'Longer passes cause low oxygen and dysrhythmias.', true],
        ['Rinse the secretions through by suctioning the saline', ''],
        ['Put the oxygen back on between passes', '', true],
        ['Rinse the tubing, turn off the suction and disconnect the catheter', ''],
        ['Coil the catheter in your gloved hand and pull the glove off over it; discard', ''],
        ['Empty the suction canister as needed; gloves off; wash your hands', ''],
        ['Give mouth care', ''],
        ['Document the procedure, the secretions and how the client tolerated it', '']] },
      { h: 'Trach care', steps: [
        ['Towel or pad over the client’s chest', ''],
        ['Loosen the caps on the hydrogen peroxide and the saline', ''],
        ['Wash your hands; a clean glove on your nondominant hand', ''],
        ['Remove the soiled dressing into a biohazard bag, then those gloves', ''],
        ['Look at the stoma for skin breakdown or erosion', '', true],
        ['Set the trach care equipment on the over-bed table; open the sterile kit with sterile technique', '', true],
        ['Lay out the applicators, 4×4 gauze, the pre-cut (split) dressing and the new ties', ''],
        ['Pour: half-strength peroxide (mixed 1:1 with saline) in one container, saline for rinsing in another, and wet gauze in saline in a third', ''],
        ['Unlock and remove the inner cannula with your nondominant hand', '', true],
        ['Disposable: throw it away. Reusable: soak it in the peroxide mix, clean it with the brush, rinse it in saline', ''],
        ['Dry it and put it back (or insert a new one); lock it; restart oxygen if ordered', 'The outer cannula holds the airway open; the inner one is what you clean.', true],
        ['Clean the neck plate and outer cannula with the applicators', ''],
        ['Clean the stoma with saline-moistened gauze (your checklist names the strokes: 12 to 3 o’clock, then 9 to 6 o’clock)', ''],
        ['Pat dry and apply the pre-cut sterile dressing — never cut plain gauze', 'Loose threads from cut gauze can be breathed in.', true],
        ['Never remove the old ties until the new ones are secure; tie them with the head flexed; one finger should fit under them', 'A cough can push out a tube that isn’t tied.', true],
        ['Discard the equipment, wash your hands and document', '']] }],
    flags: ['Many references now say to hyperoxygenate (100% oxygen for 30–60 seconds before and after, often with the ventilator’s oxygen button) rather than give extra bag breaths. Your checklist uses bag breaths on 100% oxygen — do that for the test-off.', 'Suction pressure: many references allow up to about 150 mm Hg for adults (AARC: under 150) — use the lowest that clears the secretions. Don’t pour saline into the airway.', 'Your checklist’s mouth-to-earlobe measurement is the one for oral and pharyngeal suctioning; for a trach, the catheter goes about the length of the tube (until the cough or slight resistance, then back about 1 cm).', 'Many agencies now clean the stoma with normal saline only — hydrogen peroxide can irritate the skin and slow healing, and is kept for crusted inner cannulas.'],
    know: ['Keep the obturator and a spare trach tube (the same size and one smaller) at the bedside.', 'Signs a client needs suctioning, and the signs of low oxygen during it (falling SpO₂, a slow or irregular heart rate, restlessness).'] },

  { id: 'chest', group: 'airway', title: 'Chest tube care', nrs: 'Lab · week 4', goal: 'Draining air and fluid from the pleural space and keeping them from flowing back, so the lung re-expands.',
    parts: [{ h: 'Care and teaching', steps: [
      ['Check the tubing for kinks and loops', 'A dependent loop fills with fluid and stops the drainage.', true],
      ['Keep the tubing close to the client in bed — not under them, not hanging over the rail; extra tubing coiled loosely on the bed', ''],
      ['Leave enough slack to move in bed without pulling on the tube', ''],
      ['Never clamp the tube yourself', 'Clamping can trap air and cause a tension pneumothorax.', true],
      ['Assess the tube and the drainage system at the start of the shift and every hour', '', true],
      ['Never lift the drainage system above chest level', 'Drainage would flow back into the chest.', true],
      ['Keep a dressing over the insertion site, clean and dry (your checklist’s teaching: change it every 7 days)', '']] },
      { h: 'Evaluate', steps: [
        ['Assess the client’s physical and emotional state', ''],
        ['Check that the client can manage daily activities with the drainage system', ''],
        ['Check that the collection system is working; the type and amount of drainage', '', true],
        ['Breathing and vital signs', '', true],
        ['Record and report changes', '']] }],
    flags: ['Your med-surg book (Chapter 24, Box 24.9) adds: gentle bubbling in the water-seal chamber when the client breathes out, coughs or moves is expected; continuous bubbling means an air leak — notify the surgeon. Tidaling (the water rising and falling with breathing) is expected; when it stops, the lung may have re-expanded or the tube may be blocked. Keep at least 2 cm of water in the water seal. Clamp only briefly — to change the system or find an air leak. Milk the tube only if the provider asks (hand over hand, never stripping).', 'Call the surgeon or rapid response for: the trachea off midline, sudden or worse shortness of breath, SpO₂ under 90%, drainage over 70 mL an hour, visible eyelets, drainage stopping in the first 24 hours. If the tube falls out, cover the site with dry sterile gauze; if it disconnects, put the end in sterile water below chest level.', 'Keep sterile gauze and padded clamps at the bedside.'],
    links: [['Exam 2 Map.html#24-lung-cancer-and-the-chest-tube', 'Chest tubes (Exam 2 map, Chapter 24)']] },

  // ===== Catheters and mobility =====
  { id: 'foley', group: 'elim', title: 'Indwelling (Foley) catheter: insertion and removal', goal: 'Draining the bladder with sterile technique, so the catheter doesn’t cause a urinary tract infection.',
    parts: [
      { h: 'Getting ready', steps: [
        ['Check the order and the reason for the catheter', 'Catheters are a top cause of hospital infections — each day one stays in matters.', true],
        ['Identify the client', '', true],
        ['Explain what will happen and what it will feel like', ''],
        ['Privacy and comfort, with good access', ''],
        ['Position: on the back, knees bent and apart, heels toward the buttocks (dorsal recumbent)', ''],
        ['Drape: bath blanket in a diamond, a corner over the abdomen; top linens to the foot of the bed; gown up toward the abdomen', ''],
        ['Look at the genital area; give perineal care if needed', 'Cleaning first lowers the number of bacteria you could push up the urethra.'],
        ['Check the package for tampering and the expiration date; read the maker’s guide', ''],
        ['Open the tray and arrange the items', ''],
        ['Put on sterile gloves', '', true],
        ['Pour the antiseptic onto the cotton balls (or open the swabs)', ''],
        ['Prepare the lubricant', ''],
        ['Attach the prefilled syringe to the balloon port (your checklist tests the balloon here)', '']] },
      { h: 'Female', steps: [
        ['With your nondominant hand spread the labia minora to see the urinary meatus — that hand stays there and is now not sterile', '', true],
        ['Clean with one downward stroke per antiseptic swab', 'Front to back keeps stool bacteria away; one stroke per swab never brings dirt back.', true],
        ['Lubricate the tip generously (the first 2–5 cm)', ''],
        ['As the client bears down, insert into the urethra; advance gently until urine flows', 'Bearing down relaxes the sphincter.', true],
        ['Advance 1–2 inches more', 'So the balloon inflates in the bladder, not in the urethra.', true],
        ['Inflate the balloon with the 10 mL of water; tug gently to check it’s anchored', ''],
        ['Secure the catheter to the thigh; drainage bag below the bladder', 'Urine flowing back from the bag carries bacteria into the bladder.', true],
        ['Make the client comfortable; 4 Ps', ''],
        ['Document: date and time, catheter type, that it drains, and the urine’s look, amount and odor', '']] },
      { h: 'Male', steps: [
        ['Lift the penis; pull back the foreskin if uncircumcised', ''],
        ['Hold the penis at 90 degrees to the body and pull gently upward to straighten the urethra (nondominant hand)', 'A straight urethra lets the catheter pass.', true],
        ['Clean the meatus in circles, from the inside out', '', true],
        ['Lubricate the first 3–4 inches (8–10 cm) generously', ''],
        ['Advance gently 10–12 inches (25–30 cm) until urine flows, then 1–2 inches more', 'The balloon must be past the prostate, in the bladder.', true],
        ['Inflate the balloon with the 10 mL of water; tug gently', ''],
        ['Return the foreskin over the head of the penis', 'A foreskin left pulled back can swell and trap the penis (paraphimosis).', true],
        ['Secure the catheter to the thigh; bag below the bladder', '', true],
        ['Make the client comfortable; 4 Ps; document', '']] },
      { h: 'Removal', steps: [
        ['Move the top linen to the foot of the bed; waterproof pad under the perineal area; lift the gown', ''],
        ['Empty the bag into a measuring container', ''],
        ['Remove the catheter holder', ''],
        ['Attach a syringe to the balloon port and let the water come out — all of it', 'A partly filled balloon tears the urethra.', true],
        ['Remove the catheter slowly; look at it for blood, mucus or signs of infection', ''],
        ['Send the tip for culture if ordered', ''],
        ['Clean and dry the perineal area', ''],
        ['Teach: drink fluids; report burning, urgency or not being able to void', 'The client should void within about 6–8 hours.'],
        ['4 Ps and document', '']] }],
    flags: ['Your checklist doesn’t say to put the foreskin back after a male catheterization — always do it.', 'Many catheter makers now say not to pre-test the balloon (it can crease the balloon). Your checklist includes it — do it for the test-off unless told otherwise.'] },

  { id: 'mobility', group: 'elim', title: 'Crutches, cane and walker', goal: 'Walking safely with the right device, the right fit and the right gait for the client’s weight bearing.',
    parts: [
      { h: 'Crutches: fit and stance', steps: [
        ['Check the order (weight-bearing status)', '', true],
        ['Hand hygiene; introduce yourself; two identifiers; explain why', ''],
        ['Assess LOC, vital signs, height and weight', ''],
        ['Assess gait, weight bearing on each leg, and whether the client can follow instructions', ''],
        ['Inspect the crutches: length, rubber tips, axillary pads', ''],
        ['Sturdy low-heeled nonskid shoes; gait (safety) belt on', '', true],
        ['Crutch length: from the axilla to 6–8 inches (15–20 cm) out from the heel', ''],
        ['Dangle the client first; stand facing them with a wide base of support', 'Catches dizziness from a blood-pressure drop before standing.'],
        ['Stand into the tripod position (crutches out to the sides and ahead)', 'A wide triangle is the most stable base.'],
        ['Hand grips set so the elbows bend about 30 degrees', ''],
        ['Two fingerbreadths between the axilla and the pad', 'Weight on the armpits damages the brachial plexus nerves.', true],
        ['Weight on the hand grips, not the armpits', '', true],
        ['Crutches slightly ahead and out to the side of each foot (about 6–8 inches from the foot); back straight, slightly bent at the hips', ''],
        ['Move the crutches and the affected leg together, then shift weight to the strong leg', '']] },
      { h: 'The gaits', steps: [
        ['Four-point (partial weight bearing on both legs, the most stable): right crutch, left foot, left crutch, right foot — even steps, no pauses', ''],
        ['Two-point (weakness in both legs, poor coordination): one crutch and the opposite foot together, then the other crutch and the other foot', 'Faster than four-point, still two points on the floor.'],
        ['Three-point (one leg can’t bear weight): both crutches and the affected leg forward together, then the strong leg', 'The crutches take the weight the weak leg can’t.'],
        ['Swing-to and swing-through (legs paralyzed or braced): crutches about 6 inches ahead, weight on the hands with elbows straight, swing the body to (or past) the crutches, landing about 12 inches ahead of them', '']] },
      { h: 'Cane', steps: [
        ['A cane with an intact rubber tip', ''],
        ['Tip 6–10 inches (15–25 cm) to the side and about 6 inches in front of the foot', ''],
        ['Hold it on the strong (unaffected) side', 'It widens the base on the side opposite the weak leg, the way your arm swings naturally.', true],
        ['Handgrip at hip level; elbow bent 15–30 degrees as you lean on it', ''],
        ['Move the cane and the weak leg forward together, then the strong leg; look straight ahead', '']] },
      { h: 'Walker (standing up from a chair, then walking)', steps: [
        ['Choose the right walker; lock the brakes of the chair or wheelchair', '', true],
        ['Scoot to the front of the seat, feet under you, toes below the chair’s edge', ''],
        ['Push up with both hands on the chair arms (or one on the chair and one on the walker) — never pull up on the walker', 'Pulling tips the walker over.', true],
        ['Don’t lean on one side of the walker as you stand', ''],
        ['Lean forward until your feet take some weight; stand mainly with your legs, arms for balance', ''],
        ['Test your balance before walking', '', true],
        ['Standard walker: lift it and set it about one step ahead, step into it with the weak leg, then the strong leg', ''],
        ['Rolling walker: keep it close and roll it ahead as you walk; take short steps if your balance is poor', ''],
        ['To turn: stay inside the walker’s frame, roll it around without twisting your back; always face the front of it', '']] }],
    flags: ['Your checklist’s two-point steps are worded unclearly; the pattern is always a crutch and the opposite foot moving together.', 'Your checklist doesn’t spell out walking with a standard walker; the steps above are the usual ones.'] },

  // ===== Mother and newborn =====
  { id: 'newborn', group: 'ob', title: 'Newborn physical exam', goal: 'Finding the conditions that need early treatment — and reassuring parents about what’s normal.',
    parts: [{ h: 'What to check', steps: [
      ['Weight, length, muscle tone; reflexes (Moro, grasp, suck, rooting); feeding', ''],
      ['Skin: pallor, jaundice, cyanosis, rashes, birthmarks', ''],
      ['Head: anterior fontanelle, skull shape and size, scalp swellings or birthmarks', 'A bulging fontanelle can mean raised pressure; a sunken one, dehydration.'],
      ['Face: low-set or simple ears, inner eye folds, slant of the eyes, symmetry of the face and mouth, ear tags or pits, a small jaw', 'Patterns can point to a syndrome.'],
      ['Eyes: red reflex (cataract), yellow sclera, a gap in the iris (coloboma)', ''],
      ['Mouth: cleft lip or palate, central cyanosis, teeth', ''],
      ['Heart: cyanosis, fast breathing or a big liver (heart failure), murmurs, femoral pulses (weak in coarctation), where the apex beat is (dextrocardia)', 'Weak femoral pulses are a classic sign of coarctation of the aorta.', true],
      ['Chest: breathing rate, signs of distress, even chest movement', '', true],
      ['Abdomen: distention or green (bile-stained) vomit, kidneys you can feel, a big liver or spleen, wall defects, the cord’s vessels (two arteries, one vein)', 'Bile-stained vomiting is an emergency — possible bowel obstruction.', true],
      ['Limbs: clubfoot, extra or fused fingers and toes, a single palm crease and a wide gap between the first toes (Down syndrome), contractures, missing radius bones', ''],
      ['Back and spine: spina bifida, a deep sacral dimple', ''],
      ['Hips: Barlow and Ortolani tests for developmental hip dysplasia; ask about risks (breech birth, family history)', ''],
      ['Genitalia and anus: the urethral opening on the underside (hypospadias), undescended testes, ambiguous genitalia, no anal opening (imperforate anus)', '']] }] },

  { id: 'postpartum', group: 'ob', title: 'Postpartum head-to-toe assessment', goal: 'Catching bleeding, infection, retention and clots early in the postpartum period — and teaching as you go.',
    parts: [{ h: 'Head to toe', steps: [
      ['Breasts: firmness, fullness, tenderness, shine, shape; sore, red, cracked or bleeding nipples; encourage a support bra whether or not she breastfeeds', ''],
      ['Fundus: firm or boggy? If boggy, massage gently until firm and note any bleeding or clots expelled', 'A boggy uterus can’t clamp down on the placental site — the main cause of postpartum hemorrhage.', true],
      ['Fundal height: have her void, then lie flat; it should drop about one fingerbreadth below the umbilicus each day (a little faster when breastfeeding, from the oxytocin)', ''],
      ['High or pushed to one side: suspect a full bladder (or retained placental pieces)', 'A full bladder pushes the uterus up and keeps it from contracting.', true],
      ['Cesarean: the dressing or incision — redness, drainage, edges together; bowel sounds', ''],
      ['Lochia: color, amount, odor, pads used. Rubra (bright red) for 2–3 days, then serosa (pinkish, watery), then alba (thin, whitish) by about 10–14 days', ''],
      ['Foul-smelling lochia → suspect infection; report odor, heavy bleeding or clots', '', true],
      ['Episiotomy or tear: REEDA (redness, edema, ecchymosis, drainage, approximation); look for a hematoma; medicate for pain; check for hemorrhoids', ''],
      ['Bladder: voiding how often and how much? Distended? Catheter — when removed? She should void within 6 hours of birth or catheter removal; measure the first three voids (each at least 150 mL)', 'Frequent small voids suggest retention or infection.', true],
      ['Bowels: a movement by the second day? Stool softener or laxative; fluids, fruit, vegetables, walking', ''],
      ['Legs: swelling, warmth, redness, tenderness of one calf; chart circulation', ''],
      ['Teaching as you go: her care, perineal care (with each bathroom trip), why sitz baths, hemorrhoid care, why early walking (especially after a cesarean)', ''],
      ['Psychosocial: bonding (stroking, talking to, cuddling the baby); her mood — explain the normal hormonal ups and downs, and tell the family too', '']] }],
    flags: ['Your checklist says to check Homans’ sign. Current guidance (and your Exam 2 notes) say not to use it — it misses most clots, flags legs that don’t have one, and could dislodge a clot. Look for one-sided swelling, warmth, redness and tenderness instead.'] },

  // ===== Documentation =====
  { id: 'charting', group: 'doc', title: 'Charting and documentation', goal: 'If you didn’t write it down, it didn’t happen: the chart carries the client’s care to the next nurse and protects you both.',
    parts: [
      { h: 'Good charting', steps: [
        ['Be objective: describe what you found, then what you did about it', '', true],
        ['Include the date and time, the client, and your name and title', ''],
        ['Assessment: vital signs, pain level, test results', ''],
        ['Any incident; changes in behavior, well-being or emotional state; changes in care given; instructions for further care', ''],
        ['Use numbers and plain, factual words — concise and easy to read, with every important detail', ''],
        ['Keep the electronic record secure: your own login, never shared; no client details outside the record', '', true]] },
      { h: 'The formats', steps: [
        ['Narrative: a time-stamped, head-to-toe description in sentences (your checklist’s sample note goes system by system: neuro, skin, lungs, heart, abdomen, extremities, lines, elimination, safety, teaching)', ''],
        ['SOAP: Subjective (what the client says), Objective (what you see, hear, feel and measure, plus test results), Assessment (what it means), Plan (what happens next)', ''],
        ['Focus charting: just the area of the complaint and what goes with it (used mostly in the emergency department)', ''],
        ['Functional assessment: mobility, transfers and activities of daily living — a baseline for rehabilitation', ''],
        ['Primary assessment: a quick check for life threats; secondary assessment: vital signs, reassessment and the fuller exam', '']] }],
    know: ['EMR and EHR are used interchangeably: digital records that can follow the client between providers, which makes security (passwords, encryption) essential.', 'DocuCare is the practice EHR used in school.'] }
];
